<?php session_name('VS_ADMIN');session_start();if(!isset($_SESSION['user_id'])||($_SESSION['user_role']??'')!=='admin'){header('Location: login.php');exit;}require_once '../config/app.php';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VS Travells Admin</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><section class="admin-shell"><aside class="admin-sidebar"><div><span class="eyebrow">VS TRAVELLS</span><h2>Admin Console</h2></div><button class="side-link active" data-tab="overview">Overview</button><button class="side-link" data-tab="requests">Booking Requests <span id="pendingCount" class="side-count">0</span></button><button class="side-link" data-tab="bookings">All Bookings</button><button class="side-link" data-tab="vehicles">Vehicles</button><button class="side-link" data-tab="customers">Customers</button><a class="side-link" href="logout.php">Admin Logout</a></aside><div class="admin-main"><div class="admin-top"><div><span class="eyebrow dark">ADMIN DASHBOARD</span><h1>Welcome, <?php echo htmlspecialchars($_SESSION['user_name']??'Admin');?>.</h1></div><span class="sync-chip">Auto-sync active</span></div><div id="adminMsg"></div>
<section class="admin-tab active" id="tab-overview"><div id="adminStats" class="stat-grid admin-stats"></div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>Recent bookings</h2><button class="text-btn" onclick="showTab('bookings')">View all</button></div><div id="recentBookings"></div></div><div class="panel revenue-card"><span class="eyebrow">REVENUE</span><h2>Total demo revenue</h2><strong id="revenueBig">₹0</strong><p id="paidCount">0 paid bookings</p><div id="recentPayments"></div></div></div></section>
<section class="admin-tab" id="tab-requests"><div class="panel-head"><div><h2>Booking Requests</h2><p class="muted">Review customer, vehicle, dates, locations and total before approving.</p></div></div><div id="requestsList" class="request-list"></div></section>
<section class="admin-tab" id="tab-bookings"><div class="panel"><h2>All Bookings</h2><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Vehicle / Route</th><th>Dates</th><th>Total</th><th>Payment</th><th>Status / Action</th></tr></thead><tbody id="allBookings"></tbody></table></div></div></section>
<section class="admin-tab" id="tab-vehicles"><div class="panel"><h2 id="vehicleFormTitle">Add Vehicle</h2><form id="vehicleForm" class="form-grid vehicle-form"><input type="hidden" id="vid"><input id="vname" placeholder="Vehicle name" required><select id="vtype"><option>Car</option><option>Bike</option></select><input id="vreg" placeholder="Registration number"><input type="number" min="1" id="vprice" placeholder="Price per day" required><select id="vstatus"><option>Available</option><option>Booked</option><option>On Rent</option><option>Maintenance</option></select><input type="number" min="1" id="vseats" placeholder="Seats"><input id="vfuel" placeholder="Fuel type (Petrol/Diesel/EV)"><input id="vtrans" placeholder="Transmission"><input id="vimage" placeholder="Vehicle image URL"><textarea id="vdesc" placeholder="Description"></textarea><button class="btn" id="vehicleSubmit">Add vehicle</button><button type="button" class="btn secondary" onclick="resetVehicleForm()">Clear</button></form></div><div id="adminVehicles" class="vehicle-admin-grid"></div></section>
<section class="admin-tab" id="tab-customers"><div class="panel"><h2>Customer Profiles</h2><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Licence</th><th>Bookings</th></tr></thead><tbody id="customers"></tbody></table></div></div></section></div></section>
<script>
let bookingData=[],vehicleData=[],adminBusy=false;async function adminFetch(url,options={}){const r=await fetch(url,{credentials:'include',...options});let j={success:false,message:'Unexpected server response.'};try{j=await r.json()}catch(e){}if(r.status===401){location.href='login.php';throw new Error('Session expired')}return j};document.querySelectorAll('.side-link[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));function showTab(n){document.querySelectorAll('.admin-tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.side-link').forEach(x=>x.classList.remove('active'));document.getElementById('tab-'+n).classList.add('active');document.querySelector(`[data-tab="${n}"]`)?.classList.add('active')}
function msg(t,ok=true){adminMsg.innerHTML=`<div class="message ${ok?'success':'error'}">${t}</div>`;setTimeout(()=>adminMsg.innerHTML='',3500)}
async function loadStats(){const j=await adminFetch('../api/admin/stats.php');if(!j.success)return;const s=j.data;adminStats.innerHTML=`<div class="stat"><span>Total vehicles</span><b>${s.vehicles}</b></div><div class="stat"><span>Customers</span><b>${s.customers}</b></div><div class="stat"><span>Pending</span><b>${s.pending}</b></div><div class="stat"><span>Confirmed</span><b>${s.confirmed}</b></div><div class="stat"><span>Active</span><b>${s.active}</b></div><div class="stat"><span>Completed</span><b>${s.completed}</b></div>`;revenueBig.textContent='₹'+Number(s.revenue).toLocaleString('en-IN');paidCount.textContent=s.paidBookings+' paid booking'+(s.paidBookings===1?'':'s');recentPayments.innerHTML=(s.recentPayments||[]).length?`<div class="mini-list">${s.recentPayments.map(p=>`<div><strong>${p.vehicle}</strong><span>₹${Number(p.amount).toLocaleString('en-IN')} • ${p.reference||'Demo paid'}</span></div>`).join('')}</div>`:'<p class="muted">No payments yet.</p>';recentBookings.innerHTML=(s.recentBookings||[]).length?`<div class="mini-list">${s.recentBookings.map(b=>`<div><strong>${b.vehicle}</strong><span>₹${Number(b.amount).toLocaleString('en-IN')}</span><em class="badge ${b.status.toLowerCase()}">${b.status}</em></div>`).join('')}</div>`:'<div class="empty-card">No bookings yet.</div>'}
async function loadBookings(){const j=await adminFetch('../api/bookings/all.php');bookingData=j.data||[];const pending=bookingData.filter(b=>b.status==='Pending');document.getElementById('pendingCount').textContent=pending.length;requestsList.innerHTML=pending.length?pending.map(b=>`<article class="request-card"><div><span class="badge pending">Pending</span><h3>${b.vehicleName}</h3><p><strong>${b.customerName}</strong> • ${b.customerEmail} • ${b.customerPhone||'No phone'}</p><p>${b.startDate} → ${b.endDate} • ${b.totalDays} days</p><p>${b.pickupLocation} → ${b.returnLocation}</p></div><div class="request-total"><small>Booking total</small><strong>₹${Number(b.totalPrice).toLocaleString('en-IN')}</strong><div><button class="btn" onclick="decide('${b.id}','Approved')">Approve</button><button class="btn danger" onclick="decide('${b.id}','Rejected')">Reject</button></div></div></article>`).join(''):'<div class="empty-card">No pending requests.</div>';allBookings.innerHTML=bookingData.length?bookingData.map(b=>`<tr><td><strong>${b.customerName}</strong><br><small>${b.customerEmail}<br>${b.customerPhone||''}</small></td><td><strong>${b.vehicleName}</strong><br><small>${b.pickupLocation} → ${b.returnLocation}</small></td><td>${b.startDate}<br>to ${b.endDate}</td><td>₹${Number(b.totalPrice).toLocaleString('en-IN')}</td><td>${b.paymentStatus}<br><small>${b.paymentReference||''}</small></td><td><span class="badge ${b.status.toLowerCase()}">${b.status}</span>${b.status==='Confirmed'&&b.paymentStatus==='Paid (Demo)'?`<br><button class="text-btn" onclick="life('${b.id}','Pickup')">Mark Picked Up</button>`:''}${b.status==='Confirmed'&&b.paymentStatus!=='Paid (Demo)'?'<br><span class="status-warning">Payment not verified — pickup blocked</span>':''}${b.status==='Active'?`<br><button class="text-btn" onclick="life('${b.id}','Return')">Mark Returned</button>`:''}${b.status==='Returned'?`<br><button class="text-btn" onclick="life('${b.id}','Complete')">Mark Completed</button>`:''}</td></tr>`).join(''):'<tr><td colspan="6">No bookings yet.</td></tr>'}
async function decide(id,decision){if(!confirm(decision+' this booking?'))return;const j=await adminFetch('../api/bookings/decision.php',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,decision})});msg(j.message,j.success);loadBookings();loadStats()}async function life(id,action){if(!confirm(action+' this rental?'))return;const j=await adminFetch('../api/bookings/lifecycle.php',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action})});msg(j.message,j.success);loadBookings();loadStats();loadVehicles()}
async function loadVehicles(){const j=await fetch('../api/vehicles/').then(r=>r.json());vehicleData=j.data||[];adminVehicles.innerHTML=vehicleData.map(v=>`<div class="admin-vehicle"><div><small>${v.type} • ${v.registrationNumber||'No registration'}</small><h3>${v.name}</h3><p>₹${Number(v.pricePerDay).toLocaleString('en-IN')}/day • ${v.status} • ${v.seats} seats • ${v.fuel}</p></div><div><button class="btn secondary" onclick="editV('${v.id}')">Edit</button><button class="btn danger" onclick="delV('${v.id}')">Delete</button></div></div>`).join('')||'<div class="empty-card">No vehicles.</div>'}
function editV(id){const v=vehicleData.find(x=>x.id===id);if(!v)return;document.getElementById('vid').value=v.id;document.getElementById('vname').value=v.name;document.getElementById('vtype').value=v.type;document.getElementById('vreg').value=v.registrationNumber||'';document.getElementById('vprice').value=v.pricePerDay;document.getElementById('vstatus').value=v.status;document.getElementById('vseats').value=v.seats;document.getElementById('vfuel').value=v.fuel||'';document.getElementById('vtrans').value=v.transmission||'';document.getElementById('vimage').value=v.image||'';document.getElementById('vdesc').value=v.description||'';document.getElementById('vehicleFormTitle').textContent='Edit Vehicle';document.getElementById('vehicleSubmit').textContent='Save changes';window.scrollTo({top:0,behavior:'smooth'})}function resetVehicleForm(){document.getElementById('vehicleForm').reset();document.getElementById('vid').value='';document.getElementById('vehicleFormTitle').textContent='Add Vehicle';document.getElementById('vehicleSubmit').textContent='Add vehicle'}
document.getElementById('vehicleForm').onsubmit=async e=>{e.preventDefault();const data={id:document.getElementById('vid').value,name:document.getElementById('vname').value.trim(),type:document.getElementById('vtype').value,registrationNumber:document.getElementById('vreg').value.trim(),pricePerDay:Number(document.getElementById('vprice').value),status:document.getElementById('vstatus').value,seats:Number(document.getElementById('vseats').value||0),fuel:document.getElementById('vfuel').value.trim(),transmission:document.getElementById('vtrans').value.trim(),image:document.getElementById('vimage').value.trim(),description:document.getElementById('vdesc').value.trim()};const editing=!!data.id;const j=await adminFetch(editing?'../api/vehicles/update.php':'../api/vehicles/create.php',{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});msg(j.message,j.success);if(j.success){resetVehicleForm();loadVehicles();loadStats()}};async function delV(id){if(!confirm('Delete this vehicle?'))return;const j=await adminFetch('../api/vehicles/delete.php',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});msg(j.message,j.success);loadVehicles();loadStats()}
async function loadCustomers(){const j=await adminFetch('../api/admin/users.php');customers.innerHTML=(j.data||[]).map(u=>`<tr><td><strong>${u.name}</strong></td><td>${u.email}</td><td>${u.phone||'—'}</td><td>${u.license||'—'}</td><td>${u.bookings||0}</td></tr>`).join('')||'<tr><td colspan="5">No customers.</td></tr>'}loadStats();loadBookings();loadVehicles();loadCustomers();setInterval(()=>{if(!document.hidden){loadStats();loadBookings();loadVehicles()}},7000);
</script></body></html>
